'use strict';
(function() {
  if (window === window.top) return;

  var params = new URL(location.href).searchParams;
  var parentOrigin = params.get('origin');
  if (!parentOrigin) return;

  var pathMatch = location.pathname.match(/\/_\/service_worker\/([^\/]+)\//);
  var version = pathMatch ? pathMatch[1] : 'proxy';
  // Public base preceding /_/service_worker/ in this iframe's own URL (e.g.
  // '/_via' behind a prefix-stripping proxy); '' on the canonical tracking host.
  var baseMatch = location.pathname.match(/^(.*)\/_\/service_worker\//);
  var basePrefix = (baseMatch && baseMatch[1]) || '';

  var swUrl = basePrefix + '/_/service_worker/' + version + '/sw.js?origin=' + encodeURIComponent(parentOrigin)
    + (basePrefix ? '&base=' + encodeURIComponent(basePrefix) : '');
  var swScope = basePrefix + '/_/service_worker';

  if ('serviceWorker' in navigator) {
    navigator.serviceWorker.register(swUrl, { scope: swScope, updateViaCache: 'all' })
      .then(function(reg) {
        return navigator.serviceWorker.ready;
      })
      .then(function(reg) {
        window.parent.postMessage({ type: 'sw_registered' }, parentOrigin);
        navigator.serviceWorker.addEventListener('message', function(e) {
          window.parent.postMessage(e.data, parentOrigin);
        });
      })
      .catch(function(err) {
        window.parent.postMessage({ type: 'sw_error', error: String(err) }, parentOrigin);
      });

    window.addEventListener('message', function(e) {
      if (e.origin !== parentOrigin) return;
      if (navigator.serviceWorker.controller) {
        navigator.serviceWorker.controller.postMessage(e.data);
      }
    });
  } else {
    window.parent.postMessage({ type: 'sw_error', error: 'ServiceWorker not supported' }, parentOrigin);
  }
})();
